import{TASKS,AUX,LEVELS,STATUSES,uid,makeZone,makePlan,active,summarize,validatePlan}from './concept-model.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='steel-concept-studio-v1';let plans=[makePlan(true)],current=plans[0].id,selected=plans[0].zones[0].id,equipment=[],storageProblem=false;
try{const stored=JSON.parse(localStorage.getItem(KEY));if(stored?.version===1&&Array.isArray(stored.plans)&&stored.plans.length){stored.plans.forEach(validatePlan);plans=stored.plans;current=plans.some(x=>x.id===stored.current)?stored.current:plans[0].id;selected=plan().zones[0]?.id;}}catch{storageProblem=true;}
function plan(){return plans.find(x=>x.id===current);}function zone(){return plan().zones.find(x=>x.id===selected);}function save(){try{localStorage.setItem(KEY,JSON.stringify({version:1,current,plans}));$('#save-status').textContent='已保存在此浏览器';}catch{$('#save-status').textContent='浏览器保存失败，请导出 JSON 备份';}}
function opts(values,value){return values.map(x=>{const [id,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`;}).join('');}
function text(id,label,value,area=false){return `<label>${label}${area?`<textarea id="${id}">${esc(value)}</textarea>`:`<input id="${id}" value="${esc(value)}">`}</label>`;}
function drawBrief(){const p=plan();$('#brief').innerHTML=text('plan-name','方案名称',p.name)+text('feed','来料与流量范围',p.feed,true)+text('product','目标产品与指标',p.product,true)+text('idea','核心构想与允许的结构',p.idea,true);for(const k of ['name','feed','product','idea'])$('#'+(k==='name'?'plan-name':k)).addEventListener('change',e=>{p[k]=e.target.value.slice(0,k==='name'?200:10000)|| (k==='name'?'未命名构想':'');save();drawPlans();});}
function drawPlans(){$('#plans').innerHTML=opts(plans.map(x=>[x.id,x.name]),current);}
function drawCatalog(){const q=$('#search').value.trim().toLowerCase();$('#catalog').innerHTML=TASKS.filter(t=>(t.name+t.refs.join(' ')+t.question).toLowerCase().includes(q)).map(t=>`<button class="task" data-task="${t.id}"><strong>＋ ${t.name}</strong><small>${t.refs.length?t.refs.join(' / '):'专项证据待补充'}</small></button>`).join('');$('#catalog').querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{const z=makeZone(b.dataset.task);plan().zones.push(z);selected=z.id;save();render();});}
function drawFlow(){const p=plan(),s=summarize(p);const card=z=>`<button class="zone ${z.id===selected?'selected':''}" data-zone="${esc(z.id)}" style="width:${115+z.length*18}px"><span class="aux top">${esc(z.aux.filter(x=>!/(补热|冷却|测温|在线)/.test(x)).join(' · ')||'喷吹／加料待选')}</span><strong>${esc(z.name)}</strong><small>${z.length.toFixed(1)} m · ${esc(z.status)}</small><small>${esc(z.level)}</small><span class="aux bottom">${esc(z.aux.filter(x=>/(补热|冷却|测温|在线)/.test(x)).join(' · ')||'补热／检测待选')}</span></button>`;
 $('#flow').innerHTML=`<div class="lane-wrap"><div class="lane"><div class="terminal">电炉<br>出钢口</div><span class="connector"></span>${s.main.map(z=>card(z)+'<span class="connector"></span>').join('')}<div class="terminal">出口<br>连铸机</div></div></div>${s.other.map(z=>{const a=s.main.find(x=>x.id===z.anchor);return `<div class="branch"><small>${z.lane==='cycle'?'↻ 循环：从所连区抽取，处理后回到同一区':'↗ 旁路：从所连区入口分流，处理后在该区出口汇合'} · ${a?esc(a.name):'连接点待选择'}</small>${card(z)}</div>`;}).join('')}${p.zones.filter(z=>!active(z)).length?`<details><summary>暂缓／淘汰构想（不计入当前布局）</summary>${p.zones.filter(z=>!active(z)).map(z=>`<button data-zone="${esc(z.id)}">${esc(z.name)} · ${esc(z.status)}</button>`).join(' ')}</details>`:''}`;
 $('#flow').querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>{selected=b.dataset.zone;drawFlow();drawEditor();});
 $('#overview').innerHTML=`<div class="metrics"><div class="metric"><strong>${s.zones.length}</strong><span>参与布局的功能区</span></div><div class="metric"><strong>${s.mainLength.toFixed(1)} m</strong><span>主流概念占用长度</span></div><div class="metric"><strong>${s.otherLength.toFixed(1)} m</strong><span>支路／循环独立长度</span></div></div><p class="muted">功能覆盖（仅表示已安排）：</p><div class="coverage">${TASKS.filter(t=>t.id!=='custom').map(t=>`<span class="tag ${s.tasks.includes(t.id)?'on':''}">${s.tasks.includes(t.id)?'✓ ':''}${t.name}</span>`).join('')}</div>`;
 const questions=s.zones.filter(z=>z.question.trim());$('#review').innerHTML=`<div><h3>组合关系提醒</h3><ul>${s.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h3>模块研究问题</h3>${questions.length?`<ol>${questions.map(z=>`<li><strong>${esc(z.name)}</strong>：${esc(z.question)}</li>`).join('')}</ol>`:'<p>尚未记录具体问题。</p>'}<p class="muted">论证顺序：必要性 → 条件兼容 → 连续化 → 物料与能量 → 制造维护 → 仿真试验。</p></div>`;
}
function drawEditor(){const z=zone();if(!z){$('#editor').innerHTML='<h2>选择或添加功能区</h2><p class="muted">先写下想改善什么，参数留到下一轮。</p>';return;}const refs=equipment.filter(e=>TASKS.find(t=>t.id===z.task).refs.includes(e.equipment_id));const ref=equipment.find(e=>e.equipment_id===z.reference);const main=plan().zones.filter(x=>active(x)&&x.lane==='main'&&x.id!==z.id);
 $('#editor').innerHTML=`<h2>${esc(TASKS.find(t=>t.id===z.task).name)}</h2>${text('z-name','构想名称',z.name)}${text('z-effect','希望达到什么效果',z.effect,true)}<label>设备借鉴<select id="z-reference">${opts([['','暂不确定'],...refs.map(e=>[e.equipment_id,`${e.equipment_id} · ${e.name}`])],z.reference)}</select></label><div id="ref-note" class="muted">${ref?`数据包：${esc(ref.functions)}；来源 ${esc(ref.source_ids.join('、')||'未列文献')}。这是原设备参考，不能证明连续床迁移有效。`:'暂无对应证据；可先记录机制，后补文献。'}</div><label>路径<select id="z-lane">${opts([['main','连续主流'],['side','旁路：跨接一个主流区'],['cycle','循环：回到所连主流区']],z.lane)}</select></label>${z.lane!=='main'?`<label>连接的主流区<select id="z-anchor">${opts([['','待选择'],...main.map(x=>[x.id,x.name])],z.anchor||'')}</select></label>`:''}<label>概念占用长度 <output id="length-label">${z.length.toFixed(1)} m</output><input id="z-length" type="range" min="0.5" max="3" step="0.5" value="${z.length}"></label><p class="muted">0.5–3 m 为草图分配范围。流量与截面未定义，处理时间待估算。</p><details><summary>并行辅助方式 <span>${z.aux.length} 项</span></summary><fieldset><legend>可同时选择，独立条件待论证</legend>${AUX.map((a,i)=>`<label><input type="checkbox" data-aux="${i}" ${z.aux.includes(a)?'checked':''}> ${a}</label>`).join('')}</fieldset></details><label>本构想的证据成熟度<select id="z-level">${opts(LEVELS,z.level)}</select></label>${text('z-evidence','支持材料／来源编号',z.evidence,true)}<p class="muted">成熟度由你标记，系统不自动核实。设备有参考不等于该构想有工业验证。</p><label>筛选状态<select id="z-status">${opts(STATUSES,z.status)}</select></label>${text('z-question','下一轮要回答的问题',z.question,true)}<div class="actions"><button id="prev" ${plan().zones.indexOf(z)===0?'disabled':''}>向前</button><button id="next" ${plan().zones.indexOf(z)===plan().zones.length-1?'disabled':''}>向后</button><button id="duplicate">复制</button><button id="delete" class="danger">删除此区</button></div>`;
 for(const k of ['name','effect','reference','lane','anchor','level','evidence','status','question'])$('#z-'+k)?.addEventListener('change',e=>{z[k]=k==='anchor'?(e.target.value||null):e.target.value.slice(0,10000);save();drawFlow();if(['reference','lane','status'].includes(k))drawEditor();});
 $('#z-length').oninput=e=>{z.length=Number(e.target.value);$('#length-label').textContent=z.length.toFixed(1)+' m';drawFlow();save();};
 $('#editor').querySelectorAll('[data-aux]').forEach(c=>c.onchange=()=>{const a=AUX[Number(c.dataset.aux)];z.aux=c.checked?[...z.aux,a]:z.aux.filter(x=>x!==a);save();drawFlow();c.closest('details').querySelector('summary span').textContent=z.aux.length+' 项';});
 for(const [id,delta]of [['prev',-1],['next',1]])$('#'+id).onclick=()=>{const a=plan().zones,i=a.indexOf(z);[a[i],a[i+delta]]=[a[i+delta],a[i]];save();drawFlow();drawEditor();};
 $('#duplicate').onclick=()=>{const copy=structuredClone(z);copy.id=uid();copy.name+=' · 副本';plan().zones.splice(plan().zones.indexOf(z)+1,0,copy);selected=copy.id;save();drawFlow();drawEditor();};
 $('#delete').onclick=()=>{const i=plan().zones.indexOf(z);plan().zones.splice(i,1);selected=plan().zones[Math.max(0,i-1)]?.id;save();drawFlow();drawEditor();};
}
function render(){drawPlans();drawBrief();drawCatalog();drawFlow();drawEditor();}
$('#search').oninput=drawCatalog;$('#plans').onchange=e=>{current=e.target.value;selected=plan().zones[0]?.id;save();render();};
$('#new').onclick=()=>{const p=makePlan();plans.push(p);current=p.id;selected=null;save();render();};
$('#copy').onclick=()=>{const p=structuredClone(plan()),ids=new Map(p.zones.map(z=>[z.id,uid()]));p.id=uid();p.name+=' · 副本';p.zones.forEach(z=>{z.id=ids.get(z.id);z.anchor=ids.get(z.anchor)||null;});plans.push(p);current=p.id;selected=p.zones[0]?.id;save();render();};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({format:'steel-concept-studio',version:1,plan:plan()},null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='refining-concept.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('文件超过 2 MB。');const d=JSON.parse(await f.text());if(d.format!=='steel-concept-studio'||d.version!==1)throw Error('不是受支持的概念方案文件。');const p=validatePlan(d.plan);p.id=uid();plans.push(p);current=p.id;selected=p.zones[0]?.id;save();render();}catch(err){$('#save-status').textContent='导入失败：'+err.message;}finally{e.target.value='';}};
render();$('#save-status').textContent=storageProblem?'旧草稿未能恢复，请检查导出备份；当前新草图尚未保存':'编辑后自动保存到当前浏览器';
fetch('./evidence/downloads/core-data.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(d=>{equipment=d.equipment;drawEditor();}).catch(()=>{$('#ref-note')?.replaceChildren(document.createTextNode('设备数据包未载入，参考选择暂不可用；请刷新或打开数据支持库。'));});
